do $bm_remove_dates$ declare col text; begin
 for col in select jsonb_array_elements_text(current_setting('vb_brand_map.cleanup_manifest')::jsonb->'added_dates') loop
  if col not in ('filing_date','registration_date','uspto_status_date') then raise exception 'Unowned date field'; end if;
  execute format('alter table public.vb_marks drop column %I',col);
 end loop;
end $bm_remove_dates$;
drop table vb_private.brand_map_race_runs;
do $bm_cleanup_result$ declare r jsonb:=current_setting('vb_brand_map.cleanup_manifest')::jsonb; begin
 if (select encode(sha256(convert_to(coalesce(jsonb_agg(item order by item::text),'[]'::jsonb)::text,'UTF8')),'hex') from (
  select jsonb_build_object('relation',n.nspname||'.'||c.relname,'oid',c.oid,'kind',c.relkind,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl,'owner',c.relowner) item
    from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','vb_private')
  union all select jsonb_build_object('column',a.attrelid,'n',a.attnum,'name',a.attname,'type',a.atttypid,'mod',a.atttypmod,'null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid))
    from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname in ('public','vb_private') and a.attnum>0 and not a.attisdropped
  union all select jsonb_build_object('function',p.oid,'name',n.nspname||'.'||p.proname,'args',p.proargtypes::text,'result',p.prorettype,'source_hash',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl,'owner',p.proowner)
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','vb_private')
  union all select jsonb_build_object('constraint',x.oid,'definition',pg_get_constraintdef(x.oid)) from pg_constraint x join pg_namespace n on n.oid=x.connamespace where n.nspname in ('public','vb_private')
  union all select jsonb_build_object('trigger',t.oid,'definition',pg_get_triggerdef(t.oid)) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','vb_private')
  union all select jsonb_build_object('policy',to_jsonb(p)) from pg_policies p where p.schemaname in ('public','vb_private')
  union all select jsonb_build_object('namespace',n.nspname,'acl',n.nspacl,'owner',n.nspowner) from pg_namespace n where n.nspname in ('public','vb_private')
) metadata) is distinct from r->>'baseline_schema' or (select coalesce(jsonb_agg(to_jsonb(e) order by e.extname),'[]'::jsonb) from pg_extension e) is distinct from r->'baseline_extensions' or pg_temp.brand_map_preservation_snapshot() is distinct from r->'baseline_rows' then raise exception 'Preservation check failed: cleanup transaction rolls back'; end if;
 if exists(select 1 from auth.users where id in ('7da00277-4ee2-4719-bfa4-43e77f4fb6ed'::uuid,'eb1493cf-c9fe-4956-a57e-0ce120c55c02'::uuid)) or exists(select 1 from public.vb_clients where id='2ba5b51e-62d8-48db-915f-b273e84736bb'::uuid) or exists(select 1 from public.vb_marks where id in ('e618603b-0870-444b-b05c-002ec03d3497'::uuid,'a9ae4510-128c-4782-b5b7-e7b8b2fcea6c'::uuid,'c02015f4-14e3-4f15-9292-09774decc262'::uuid,'fb750360-1320-4bea-8e2a-f323f2176593'::uuid,'2b2bb3c7-56ae-4b22-8696-254abdc9bc81'::uuid,'c491758e-0988-491a-bf15-0e9d497ce306'::uuid)) or exists(select 1 from vb_private.audit_events where client_id='2ba5b51e-62d8-48db-915f-b273e84736bb'::uuid) then raise exception 'Fixture leftovers'; end if;
 perform set_config('vb_brand_map.race_report',jsonb_build_object('status','CLEANUP_VERIFIED','run_id','813aabca-15c9-45f8-8f3b-06a582182bc4','preexisting_rows_and_rules_preserved',true,'audit_sequence_gaps_possible',true,'completed_cases',r->'completed')::text,true);
end $bm_cleanup_result$;
reset role;
select current_setting('vb_brand_map.race_report')::jsonb as brand_map_race_report;
drop function pg_temp.brand_map_preservation_snapshot();
commit;
